import{_ as i,o as s,c as t,a4 as a}from"./chunks/framework.Y6MpCTxc.js";const k=JSON.parse('{"title":"Codex plugin","description":"Install the JSVision Codex plugin, invoke its skills, verify generated guidance, and diagnose host integration failures.","frontmatter":{"title":"Codex plugin","description":"Install the JSVision Codex plugin, invoke its skills, verify generated guidance, and diagnose host integration failures."},"headers":[],"relativePath":"guide/codex-plugin.md","filePath":"guide/codex-plugin.md"}'),n={name:"guide/codex-plugin.md"};function l(d,e,r,o,p,h){return s(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="codex-plugin" tabindex="-1">Codex plugin <a class="header-anchor" href="#codex-plugin" aria-label="Permalink to &quot;Codex plugin&quot;">​</a></h1><p>The JSVision Codex plugin gives Codex version-matched framework guidance, project scaffolding, static diagnostics, and deterministic headless rendering. It works in a consumer project that installs JSVision from npm; you do not need a JSVision monorepo checkout.</p><p>This integration course is for developers who have completed <a href="/jsvision/pr-preview/pr-202/guide/install-and-packages.html">Install &amp; packages</a> and want Codex to follow JSVision&#39;s supported APIs and quality workflow. By the end, you will be able to:</p><ul><li>install the tagged JSVision marketplace and plugin;</li><li>select or explicitly invoke the right bundled skill;</li><li>distinguish the canonical skill sources from the assembled plugin distribution; and</li><li>verify installation, recover from stale guidance, and diagnose helper failures.</li></ul><p>Plugin installation and skill discovery happen in the Codex host, outside the browser documentation runtime. This course therefore uses a verified installation transcript and repository integrity evidence instead of an embedded live lab.</p><h2 id="install-from-the-marketplace" tabindex="-1">Install from the marketplace <a class="header-anchor" href="#install-from-the-marketplace" aria-label="Permalink to &quot;Install from the marketplace&quot;">​</a></h2><p>Add the marketplace at the tag matching the stable JSVision packages in your project, then install the plugin:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> marketplace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blendsdk/jsvision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ref</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v1.5.3</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsvision-plugin@jsvision-marketplace</span></span></code></pre></div><p>Start a new Codex thread after installation so its bundled skills are discovered. The plugin version stays in lockstep with the stable <code>@jsvision/*</code> package version. Pinning the marketplace tag makes the guidance reproducible for that release instead of silently following a moving branch.</p><p>You can confirm the configured source and installed plugin without changing them:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> marketplace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>Codex also exposes <code>/plugins</code> in an interactive CLI session. The browser lets you inspect marketplace entries and enable or disable an installed plugin. See the official <a href="https://learn.chatgpt.com/docs/plugins" target="_blank" rel="noreferrer">Codex plugin documentation</a> for host and surface availability.</p><h2 id="invoke-the-plugin" tabindex="-1">Invoke the plugin <a class="header-anchor" href="#invoke-the-plugin" aria-label="Permalink to &quot;Invoke the plugin&quot;">​</a></h2><p>Describe the desired outcome normally and let the main <code>jsvision</code> skill activate, or name it explicitly when you want to make the workflow unambiguous:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Use $jsvision to build a keyboard-first inventory application.</span></span></code></pre></div><p>The installed plugin ships four skills:</p><table tabindex="0"><thead><tr><th>Skill</th><th>Use it when you need</th></tr></thead><tbody><tr><td><code>$jsvision</code></td><td>Architecture, public APIs, layout, reactivity, components, localization, testing, or production review</td></tr><tr><td><code>$jsvision-new-app</code></td><td>A standalone Node 22+, ESM TypeScript starter using published JSVision packages</td></tr><tr><td><code>$jsvision-doctor</code></td><td>TypeScript-backed diagnosis of layout, lifecycle, focus, modal, rendering, or NodeNext mistakes and footguns</td></tr><tr><td><code>$jsvision-render</code></td><td>A deterministic headless text screenshot at normal or constrained sizes, optionally after driven key input</td></tr></tbody></table><p>The main skill inspects the consumer project&#39;s installed versions and public declarations before making version-sensitive claims. It should use public package entry points; it should not copy internal monorepo imports into consumer code.</p><h2 id="scaffold-a-standalone-application" tabindex="-1">Scaffold a standalone application <a class="header-anchor" href="#scaffold-a-standalone-application" aria-label="Permalink to &quot;Scaffold a standalone application&quot;">​</a></h2><p>Ask Codex to use <code>$jsvision-new-app</code>, describe the application, and choose a starter. The generator offers basic, form, grid, and dashboard starters. It detects npm, Yarn, pnpm, or Bun from project metadata and lockfiles, asks when detection is ambiguous, and otherwise falls back to npm.</p><p>The skill resolves its installed directory and runs this command shape:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-director</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/new-jsvision-app.mjs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --package-manager</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">manage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Add <code>--template form|grid|dashboard</code> for a specialized starter, or <code>--list</code> to inspect the available templates. The default destination is a new subdirectory. The generator requires explicit confirmation before writing into the current directory with <code>--current-dir</code>, refuses path traversal and conflicting files, and installs dependencies with the selected package manager.</p><p>Generated applications export <code>buildApp()</code> for tests and headless rendering while keeping terminal startup behind a direct-execution guard.</p><h2 id="diagnose-a-project" tabindex="-1">Diagnose a project <a class="header-anchor" href="#diagnose-a-project" aria-label="Permalink to &quot;Diagnose a project&quot;">​</a></h2><p>The <code>$jsvision-doctor</code> uses the consumer project&#39;s TypeScript compiler, scans a file or directory, and reports concrete errors, warnings, and informational findings:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-director</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/jsvision-doctor.mjs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><p>If TypeScript is missing, Codex must ask for approval before installing it as a development dependency. Fix or explain each finding, then rerun the doctor until the output is understood. A clean result is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jsvision-doctor: no issues found ✓</span></span></code></pre></div><p>The doctor is static evidence. Follow it with headless rendering and interaction tests when the problem is visual or behavioral.</p><h2 id="render-and-interact-headlessly" tabindex="-1">Render and interact headlessly <a class="header-anchor" href="#render-and-interact-headlessly" aria-label="Permalink to &quot;Render and interact headlessly&quot;">​</a></h2><p><code>$jsvision-render</code> accepts a module exporting <code>buildApp</code>, <code>build</code>, or a default factory. The skill runs the renderer through the consumer project&#39;s <code>tsx</code> so TypeScript modules load in the consumer-project environment:</p><p>Use the command form for the consumer project&#39;s package manager. The <code>--</code> after <code>npm exec</code> keeps renderer flags out of npm&#39;s own argument parser:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-director</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/render-app.mjs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">modul</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--export </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">name]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--pick </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">property]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--size </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">80x24]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--keys </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tab enter&quot;]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-director</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/render-app.mjs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">modul</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--export </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">name]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--pick </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">property]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--size </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">80x24]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--keys </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tab enter&quot;]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-director</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/render-app.mjs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">modul</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--export </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">name]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--pick </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">property]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--size </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">80x24]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--keys </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tab enter&quot;]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bunx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-director</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/render-app.mjs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">modul</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--export </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">name]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--pick </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">property]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--size </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">80x24]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--keys </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tab enter&quot;]</span></span></code></pre></div><p>Render at normal and constrained terminal sizes. Use <code>--keys</code> to capture important focus, navigation, and mutation states. If the module has another entry shape, add a small adapter export instead of executing an uncontrolled terminal startup path. The renderer resolves JSVision from the consumer project and never connects to a real terminal.</p><h2 id="canonical-source-and-generated-distribution" tabindex="-1">Canonical source and generated distribution <a class="header-anchor" href="#canonical-source-and-generated-distribution" aria-label="Permalink to &quot;Canonical source and generated distribution&quot;">​</a></h2><p>The repository separates human-reviewed guidance from the installable copy:</p><table tabindex="0"><thead><tr><th>Path or command</th><th>Ownership and purpose</th></tr></thead><tbody><tr><td><code>tools/jsvision-skill/</code></td><td>Canonical, agent-neutral skill source and the source of truth for semantic guidance</td></tr><tr><td><code>plugins/jsvision-plugin/skills/jsvision/</code></td><td>Assembled distribution copy; generated by synchronization and never edited directly</td></tr><tr><td><code>plugins/jsvision-plugin/.codex-plugin/plugin.json</code></td><td>Installable plugin identity, version, capabilities, and skill root</td></tr><tr><td><code>.agents/plugins/marketplace.json</code></td><td>Marketplace name, local source, installation policy, and category used to package and test the repository plugin</td></tr><tr><td><code>yarn plugin:update</code></td><td>Regenerates API pages and recipe snippets, records source-impact evidence, then assembles the canonical skill copy</td></tr><tr><td><code>yarn plugin:check</code></td><td>Verifies manifests, links, canonical/distributed equality, generated snippets and API pages, templates, and coverage</td></tr></tbody></table><p>When framework work affects a mapped plugin surface, review the references reported by the impact tool, edit the canonical source where necessary, run <code>yarn plugin:update</code>, and include the regenerated distribution in the same change. Editing <code>plugins/jsvision-plugin/skills/jsvision/</code> directly only creates drift; the next update replaces that edit.</p><p>Consumer projects do not run these maintainer commands. They install a tagged marketplace snapshot and use the bundled skills. The commands are documented here so maintainers and contributors know which side of the source boundary they own.</p><h2 id="how-the-integration-is-verified" tabindex="-1">How the integration is verified <a class="header-anchor" href="#how-the-integration-is-verified" aria-label="Permalink to &quot;How the integration is verified&quot;">​</a></h2><p>There is no honest browser live example for Codex installation or host-side skill discovery. The authentic substitute checks the actual repository artifacts:</p><ol><li><code>plugin.json</code> and <code>marketplace.json</code> parse, agree on <code>jsvision-plugin</code>, and resolve the plugin source.</li><li>The plugin version matches the stable JSVision package version.</li><li>Every canonical skill link, generated API page, synchronized recipe, and template passes its focused integrity rule.</li><li>The canonical and distributed skill trees match byte for byte, so stale or hand-edited generated guidance is detected.</li></ol><p>Run the same evidence gate from a JSVision checkout:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin:check</span></span></code></pre></div><p>The verified success transcript is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>check-plugin: PASS — all integrity checks green</span></span></code></pre></div><p>This proves the checked-in package is internally consistent. A consumer should separately confirm that <code>codex plugin marketplace list</code> points at the intended tag, <code>codex plugin list</code> reports the plugin, and a new thread can discover the requested skill.</p><h2 id="update" tabindex="-1">Update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;Update&quot;">​</a></h2><p>Refresh the tagged marketplace snapshot, reinstall the plugin, and start a new Codex thread:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> marketplace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsvision-marketplace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsvision-plugin@jsvision-marketplace</span></span></code></pre></div><p>To move to a newer stable release, add the marketplace again with that release tag before reinstalling. Upgrade the <code>@jsvision/*</code> packages and plugin together; otherwise the installed declarations and the plugin&#39;s release-matched guidance can differ.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>Diagnose host integration as a chain: marketplace source, installed plugin, newly discovered skill, consumer dependencies, then helper entry point.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Correction</th><th>Evidence to verify</th></tr></thead><tbody><tr><td><strong>Plugin not listed</strong></td><td>The marketplace is absent, unavailable under workspace policy, or configured at the wrong tag.</td><td>Run <code>codex plugin marketplace list</code>, then add the approved tagged source if it is missing.</td><td>The list names <code>jsvision-marketplace</code> and resolves the intended snapshot.</td></tr><tr><td><strong>Skill changes are not visible</strong></td><td>The marketplace snapshot or installed plugin is stale, or the current thread predates installation.</td><td>Upgrade the marketplace, run <code>codex plugin add jsvision-plugin@jsvision-marketplace</code>, then start a new Codex thread.</td><td><code>codex plugin list</code> reports the installed plugin and the new thread discovers its skills.</td></tr><tr><td><strong>Package and plugin versions differ</strong></td><td>JSVision packages or the marketplace tag were upgraded independently.</td><td>Align every <code>@jsvision/*</code> dependency with the matching tagged plugin release.</td><td>Compare installed package versions with the plugin version reported by <code>codex plugin list --json</code>.</td></tr><tr><td><strong>Doctor cannot find TypeScript</strong></td><td>The consumer project does not provide the compiler the doctor resolves.</td><td>Approve installing TypeScript as a development dependency with the project&#39;s package manager.</td><td>Rerun the doctor and retain its bounded findings or clean transcript.</td></tr><tr><td><strong>Renderer cannot resolve JSVision</strong></td><td>The rendered module&#39;s consumer project does not install <code>@jsvision/ui</code>.</td><td>Install the matching stable <code>@jsvision/ui</code> package in that project.</td><td>Rerun from the consumer root and confirm the module reaches headless construction.</td></tr><tr><td><strong>Renderer cannot find an entry</strong></td><td>The module exports neither <code>buildApp</code>, <code>build</code>, nor a default factory.</td><td>Add a small construction-only adapter export; do not invoke uncontrolled terminal startup.</td><td>Rerun and confirm a framed screen at both normal and constrained sizes.</td></tr><tr><td><strong>Integrity check reports distribution drift</strong></td><td>A generated copy was edited directly or the canonical source changed without synchronization.</td><td>Edit <code>tools/jsvision-skill/</code>, run <code>yarn plugin:update</code>, review the generated diff, then rerun <code>yarn plugin:check</code>.</td><td>The gate prints <code>check-plugin: PASS — all integrity checks green</code>.</td></tr></tbody></table><h2 id="practice-and-next-steps" tabindex="-1">Practice and next steps <a class="header-anchor" href="#practice-and-next-steps" aria-label="Permalink to &quot;Practice and next steps&quot;">​</a></h2><ol><li>Install the plugin at the stable tag matching a small JSVision project. In a new thread, ask <code>$jsvision-doctor</code> to inspect the project and explain every finding before changing code.</li><li>Ask <code>$jsvision-render</code> to capture the same screen at <code>80x24</code> and at a constrained size. Drive one important keyboard sequence and compare the frames.</li><li>In a JSVision checkout, identify which files are canonical and which are generated. Run <code>yarn plugin:check</code> and explain what each integrity category protects.</li></ol><p>Continue with <a href="/jsvision/pr-preview/pr-202/guide/layout.html">Layout</a> to build responsive terminal-cell interfaces. Use <a href="/jsvision/pr-preview/pr-202/guide/testing-headlessly.html">Testing headlessly</a> when you want to turn renderer output and driven input into deterministic tests. The <a href="/jsvision/pr-preview/pr-202/guide/">Guide map</a> shows the complete learning path.</p>`,58)])])}const g=i(n,[["render",l]]);export{k as __pageData,g as default};
